/* k13_conv2d: 2-D convolution of an image with a 15x15 filter (valid region).
 * UNIFORM cost per output pixel, compute-bound: the core of CNN layers. */
#include "common.h"
#include <omp.h>

#define KS 15

/* === KERNEL BEGIN === */
static void kernel(int h, int w, const float *img, const float *filt, float *out) {
    int oh = h - KS + 1, ow = w - KS + 1;

    /* 
     * Use OpenMP to parallelize the output pixel calculation.
     * collapse(2) is used to broaden the iteration space, ensuring all cores are 
     * utilized even if the image height 'oh' is small.
     * schedule(guided) is chosen because the target machine has a heterogeneous 
     * architecture (4 P-cores and 6 E-cores). Guided scheduling allows the faster 
     * P-cores to take on more work as they complete their chunks, balancing the 
     * load more effectively than static scheduling.
     */
    #pragma omp parallel for collapse(2) schedule(guided)
    for (int y = 0; y < oh; y++) {
        for (int x = 0; x < ow; x++) {
            float s = 0.0f;
            for (int ky = 0; ky < KS; ky++) {
                // The compiler can efficiently vectorize this inner loop since KS is small and constant.
                for (int kx = 0; kx < KS; kx++) {
                    s += img[(long)(y + ky) * w + (x + kx)] * filt[ky * KS + kx];
                }
            }
            out[(long)y * ow + x] = s;
        }
    }
}
/* === KERNEL END === */

int main(int argc, char **argv) {
    int h = (int)arg_long(argc, argv, 1, 6144), w = (int)arg_long(argc, argv, 2, 6144);
    long oh = h - KS + 1, ow = w - KS + 1;
    float *img = xmalloc((long)h * w * sizeof *img), filt[KS * KS];
    float *out = xmalloc(oh * ow * sizeof *out);
    rng_seed(13);
    for (long k = 0; k < (long)h * w; k++) img[k] = (float)rng_unit();
    for (int k = 0; k < KS * KS; k++) filt[k] = (float)rng_unit() / (KS * KS);

    double t0 = now_sec();
    kernel(h, w, img, filt, out);
    double t1 = now_sec();

    double sum = 0.0;   /* each pixel is computed in a fixed order: exact */
    for (long k = 0; k < oh * ow; k++) sum += out[k];
    report("conv2d", t1 - t0, sum);
    free(img); free(out);
    return 0;
}

